command:
set -euo pipefail; env_file="${UA_WHATBOX_ENV_FILE:-${XDG_CONFIG_HOME:-$HOME/.config}/upload-assistant/whatbox.env}"; set -a; source "$env_file"; set +a; export SSHPASS="$UA_WHATBOX_PASSWORD"; sshpass -e ssh -4 -o PubkeyAuthentication=no -o PreferredAuthentications=password -o StrictHostKeyChecking=yes artemisprime@destiny.whatbox.ca bash -s <<'REMOTE'
set -u
cd ~/Upload-Assistant-wastaken
echo inspect:
podman inspect upload-assistant-wastaken --format 'status={{.State.Status}} pid={{.State.Pid}} started={{.State.StartedAt}} finished={{.State.FinishedAt}} exit={{.State.ExitCode}} restart={{.RestartCount}}'
echo processes:
podman exec upload-assistant-wastaken sh -c 'for f in /proc/[0-9]*/cmdline; do printf "%s " "$f"; tr "\\0" " " < "$f" 2>/dev/null || true; echo; done' 2>&1 | head -80 || true
echo logs-tail:
podman logs --tail 25 upload-assistant-wastaken 2>&1 || true
REMOTE
